customCSS:
.t, .history { color: #8b949e; }
.join { color: #7ee787; }
.part, .quit { color: #8b949e; }
.kick, .error { color: #ff7b72; }
.notice { color: #d29922; }
.action { color: #d2a8ff; }
.mode, .nick, .topic, .server { color: #a5d6ff; }
.highlight { color: #c9d1d9; background-color: #264f78; border-left: 3px solid #d2a8ff; padding-left: 8px; }
.reply { color: #8b949e; border-left: 2px solid #58a6ff; padding-left: 6px; }
.oper { color: #0d1117; background-color: #d29922; }
.reactions { color: #58a6ff; background-color: #161b22; }
.card { background-color: #161b22; border-color: #8b949e; }
.card-title { color: #58a6ff; }
.card-desc { color: #8b949e; }
.daychange { color: #8b949e; border-color: #161b22; }
